perl << 'PERL'
use strict;
use warnings;

my $root = "/bench/repo";
my $store = "$root/store";

sub read_file {
    my ($p) = @_;
    open my $fh, '<', $p or return '';
    local $/; my $c = <$fh>; close $fh; return $c;
}

sub is_data_layer {
    my ($rel) = @_;
    return 1 if $rel eq 'store' || index($rel, 'store/') == 0;
    return 0;
}

# Collect persistent entity struct types from store/*.go (top-level, not Find/Update/Delete)
my @entities;
open my $sf, '<', "$root/store/entity_list.tmp" if 0;
for my $f (glob("$store/*.go")) {
    next if $f =~ /_test\.go$/;
    my $base = $f; $base =~ s/.*\///; $base =~ s/\.go$//;
    next if $base =~ /^(store|driver|common|cache|migrator|deployment_config|auth_config|user_delete)$/;
    my $content = read_file($f);
    while ($content =~ /^type\s+([A-Z][A-Za-z0-9_]*)\s+struct\s*\{/mg) {
        my $type = $1;
        next if $type =~ /^(Find|Update|Delete|RefreshTokenQueryResult|PATQueryResult|AuthenticationConfig|DeleteUserResult)/;
        push @entities, $type;
    }
}
# manual add common entity-like types
@entities = sort { $a cmp $b } qw(
    Attachment User Memo MemoRelation MemoShare Reaction Inbox
    IdentityProvider UserIdentity UserSetting InstanceSetting
);

# unique
my %seen; @entities = grep { !$seen{$_}++ } @entities;

# Collect all non-test go files outside data layer
my @files;
open my $fl, '-|', "find $root -name '*.go' ! -name '*_test.go' ! -path '*/proto/gen/*' ! -path '*/web/*'" or die $!;
while (<$fl>) {
    chomp;
    my $rel = substr($_, length($root)+1);
    next if is_data_layer($rel);
    push @files, $rel;
}
close $fl;

my %pkg_of_file;
my %type_pkg_count;
my %type_pkg_list;

for my $rel (@files) {
    my $content = read_file("$root/$rel");
    my $pkg = 'unknown';
    $pkg = $1 if $content =~ /^package\s+(\w+)/m;
    # normalize package path as directory
    my $pkgpath = $rel;
    $pkgpath =~ s/\/[^\/]+$//;
    $pkgpath = '.' if $pkgpath eq $rel;

    for my $type (@entities) {
        next unless $content =~ /\bstore\.$type\b/;
        $type_pkg_list{$type}{$pkgpath} = 1;
    }
}

my @ranked = sort {
    (scalar keys %{$type_pkg_list{$b}}) <=> (scalar keys %{$type_pkg_list{$a}})
    || $a cmp $b
} @entities;

print "Entity external package counts (by directory path):\n";
for my $type (@ranked) {
    my $count = scalar keys %{$type_pkg_list{$type}};
    print "$count\t$type\n";
    my @pkgs = sort keys %{$type_pkg_list{$type}};
    print "  " . join(", ", @pkgs[0..9]) . (@pkgs>10 ? "..." : "") . "\n" if $count;
}
PERL

